const angka = Number(inputs.angka ?? 21);

const jawaban = await notebooks.run('zz-uji-panggil-py-inti', { angka });
const dariPython = jawaban?.hasil ?? {};
const dariNode = dariPython.lewat_node ?? {};

const rantai = [
  { singgah: '1. node (ini)', bahasa: 'node', nilai: angka },
  { singgah: '2. python', bahasa: dariPython.dari ?? '—', nilai: dariPython.diterima ?? '—' },
  { singgah: '3. node (inti)', bahasa: dariNode.dari ?? '—', nilai: dariNode.diterima ?? '—' },
  { singgah: '4. kembali', bahasa: 'node → python → node', nilai: dariNode.dikembalikan ?? '—' },
];

const utuh = dariPython.diterima === angka && dariNode.diterima === angka;
const benar = dariNode.dikembalikan === angka * 2;

const ringkasan = [
  `## ${utuh && benar ? 'Lulus' : 'GAGAL'}`,
  '',
  `Dikirim **${angka}**, kembali **${dariNode.dikembalikan ?? '—'}**.`,
  '',
  utuh
    ? 'Nilainya utuh di setiap persinggahan.'
    : 'Nilainya berubah saat menyeberang. Lihat tabel — persinggahan mana yang salah.',
  '',
  bener(benar),
].join('\n');

function bener(ok) {
  return ok
    ? 'Perhitungan di ujung rantai benar (angka x 2).'
    : 'Perhitungan di ujung rantai salah.';
}

return { rantai, ringkasan };

